#include <fstream>
#include <vector>
using namespace std;
void solve(istream& in, ostream& out) {
    int n; if (!(in >> n)) return;
    vector<long long> a(n); long long total = 0;
    for (auto& x : a) { in >> x; total += x; }
    long long target = total / n, moves = 0;
    for (long long x : a) if (x > target) moves += x - target;
    out << moves << '\n';
}
int main() {
    ifstream in("haybales.in"); ofstream out("haybales.out");
    solve(in, out); return 0;
