#include <algorithm>
#include <array>
#include <fstream>
#include <numeric>
#include <vector>
using namespace std;
void solve(istream& in, ostream& out) {
    int n; if (!(in >> n)) return;
    array<vector<int>, 5> pos;
    for (int k = 0; k < 5; ++k) {
        pos[k].resize(n + 1);
        for (int j = 0, id; j < n; ++j) { in >> id; pos[k][id] = j; }
    }
    vector<int> order(n); iota(order.begin(), order.end(), 1);
    sort(order.begin(), order.end(), [&](int a, int b) {
        int before = 0;
        for (int k = 0; k < 5; ++k) before += pos[k][a] < pos[k][b];
        return before >= 3;
    });
    for (int id : order) out << id << '\n';
}
int main() {
    ifstream in("photo.in"); ofstream out("photo.out");
    solve(in, out); return 0;
}
