#include <algorithm>
#include <fstream>
#include <vector>
using namespace std;
bool noCarry(long long a, long long b) {
    while (a || b) {
        if (a % 10 + b % 10 >= 10) return false;
        a /= 10; b /= 10;
    }
    return true;
}
void search(const vector<long long>& w, int index, int count, long long sum, int& best) {
    best = max(best, count);
    if (count + static_cast<int>(w.size()) - index <= best) return;
    if (index == static_cast<int>(w.size())) return;
    if (noCarry(sum, w[index])) search(w, index + 1, count + 1, sum + w[index], best);
    search(w, index + 1, count, sum, best);
}
void solve(istream& in, ostream& out) {
    int n; if (!(in >> n)) return;
    vector<long long> w(n); for (auto& x : w) in >> x;
    int best = 0; search(w, 0, 0, 0, best); out << best << '\n';
}
int main() {
    ifstream in("escape.in"); ofstream out("escape.out");
    solve(in, out); return 0;
}
